package com.turboio.addon;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;

/** Expired-envelope renewal, original journal replay and restart safety. */
public final class MaterialRenewalTest {
 static int checks;static void yes(boolean ok){checks++;if(!ok)throw new AssertionError("Material renewal "+checks);}
 interface Work{void run()throws Exception;}static void rejects(Work work)throws Exception{checks++;try{work.run();}catch(IOException|IllegalArgumentException expected){return;}throw new AssertionError("Expected renewal rejection "+checks);}
 static Map<String,Object> row(MaterialOutbox q){return WireJson.map(q.all().get(0));}
 static byte[] absent(){return WireJson.bytes(WireJson.object("schema_version","1.0","error",WireJson.object("code","EVENT_NOT_FOUND")));}
 static byte[] expired(byte[] raw,long now){Map<String,Object> e=WireJson.map(WireJson.read(raw));e.put("event_id","synthetic-renew-old");e.put("idempotency_key","synthetic-renew-old");e.put("created_at",TaskWire.now(now-120000));e.put("expires_at",TaskWire.now(now-60000));Map<String,Object> b=WireJson.map(e.get("body"));String prior=(String)b.put("material_id","synthetic-android-renewal");for(Object item:WireJson.list(b.get("speakers"))){Map<String,Object> v=WireJson.map(item);v.put("speaker_id",((String)v.get("speaker_id")).replace(prior,"synthetic-android-renewal"));}for(Object item:WireJson.list(b.get("utterances"))){Map<String,Object> v=WireJson.map(item);if(v.get("speaker_id")!=null)v.put("speaker_id",((String)v.get("speaker_id")).replace(prior,"synthetic-android-renewal"));}return WireJson.bytes(e);}
 static void unit(File root,MaterialConnection connection,byte[] old,long now)throws Exception{
  String id=(String)WireJson.map(WireJson.map(WireJson.read(old)).get("body")).get("material_id");Set<String> allowed=Collections.singleton(id),version=Collections.singleton("1.2");File files=new File(root,"renew");String renewed;
  try(MaterialOutbox q=new MaterialOutbox(files,connection)){
   q.enqueue(old);yes(q.prepareRenewal(connection,now,Collections.emptySet())==0);yes(row(q).get("state").equals("queued"));
   yes(q.prepareRenewal(connection,now,allowed)==1);MaterialOutbox.Claim c=q.claim(now,version,allowed);yes(c.action.equals("lookup")&&c.eventId.equals("synthetic-renew-old"));
   q.finish(c,404,WireJson.bytes(WireJson.object("schema_version","1.0","error",WireJson.object("code","NOT_FOUND"))),now,0);yes(q.prepareRenewal(connection,now,allowed)==0);yes(WireJson.list(row(q).get("history")).isEmpty());
   q.resumeBlocked();c=q.claim(now,version,allowed);q.finish(c,404,absent(),now,0);yes(row(q).get("state").equals("expired"));yes(q.prepareRenewal(connection,now,Collections.emptySet())==0);yes(q.prepareRenewal(connection,now,allowed)==1);
   renewed=(String)row(q).get("payload");Map<String,Object> event=WireJson.map(WireJson.read(renewed.getBytes(StandardCharsets.UTF_8)));yes(!event.get("event_id").equals("synthetic-renew-old"));yes(event.get("expires_at").equals(connection.expires));yes(Arrays.equals(WireJson.bytes(event.get("body")),WireJson.bytes(WireJson.map(WireJson.read(old)).get("body"))));yes(WireJson.list(row(q).get("history")).size()==1);
   q.enqueue(old);yes(row(q).get("payload").equals(renewed));Map<String,Object> changed=WireJson.map(WireJson.read(old));changed.put("created_at",TaskWire.now(now-119999));rejects(()->q.enqueue(WireJson.bytes(changed)));
   c=q.claim(now,version,allowed);yes(c.action.equals("send"));
  }
  try(MaterialOutbox q=new MaterialOutbox(files,connection)){q.enqueue(old);yes(row(q).get("payload").equals(renewed));MaterialOutbox.Claim c=q.claim(now+1,version,allowed);yes(c.action.equals("lookup"));q.finish(c,200,MaterialTest.ack(c),now+1,0);yes(row(q).get("state").equals("server_stored"));yes(q.prepareRenewal(connection,now+2,allowed)==0);}
  File migration=new File(root,"migration");try(MaterialOutbox q=new MaterialOutbox(migration,connection)){q.enqueue(old);}Path state=new File(migration,"material-outbox/"+connection.binding()+"/state.json").toPath();Map<String,Object> schema1=WireJson.map(WireJson.read(Files.readAllBytes(state)));schema1.put("schema",1);Map<String,Object> oldrow=WireJson.map(WireJson.list(schema1.get("rows")).get(0));oldrow.remove("text_revision_repair");oldrow.remove("history");oldrow.remove("absence_confirmed_at");Files.write(state,WireJson.bytes(schema1));
  try(MaterialOutbox q=new MaterialOutbox(migration,connection)){yes(row(q).get("payload").equals(new String(old,StandardCharsets.UTF_8)));yes(WireJson.list(row(q).get("history")).isEmpty());q.prepareRenewal(connection,now,allowed);MaterialOutbox.Claim c=q.claim(now,version,allowed);yes(c.action.equals("lookup"));q.finish(c,200,MaterialTest.ack(c),now,0);yes(q.prepareRenewal(connection,now,allowed)==0);yes(row(q).get("state").equals("server_stored"));}
  yes(MaterialWire.positive(WireJson.map(WireJson.read(Files.readAllBytes(state))).get("schema"))==4);
  try(MaterialOutbox q=new MaterialOutbox(new File(root,"delete"),connection)){q.enqueue(old);Map<String,Object> deletion=WireJson.map(WireJson.read(old)),body=WireJson.map(deletion.get("body"));deletion.put("event_id","synthetic-delete");deletion.put("idempotency_key","synthetic-delete");deletion.put("created_at",TaskWire.now(now));deletion.put("expires_at",connection.expires);body.put("revision",2);body.put("base_revision",1);body.put("operation","delete");body.put("utterances",new ArrayList<>());body.put("speakers",new ArrayList<>());WireJson.map(body.get("full_text")).put("text","");q.enqueue(WireJson.bytes(deletion));q.prepareRenewal(connection,now,allowed);MaterialOutbox.Claim c=q.claim(now,version,allowed);yes(c.action.equals("lookup"));q.finish(c,404,absent(),now,0);yes(q.prepareRenewal(connection,now,allowed)==0);yes(q.claim(now,version,allowed)==null);yes(WireJson.list(row(q).get("history")).isEmpty());}
  System.out.println("Material renewal: "+checks+" assertions passed");
 }
 public static void main(String[] args)throws Exception{
  Map<String,Object> fixture=WireJson.map(WireJson.read(Files.readAllBytes(Paths.get(args[2]))));long now=MaterialWire.number(fixture.get("now"));MaterialConnection connection=MaterialConnection.parse(WireJson.bytes(fixture.get("connection")),now);MaterialTest.connection=connection;MaterialTest.now=now;byte[] old=expired(WireJson.bytes(WireJson.list(fixture.get("events")).get(0)),now);File root=new File(args[1]);
  if(args[0].equals("unit")){unit(root,connection,old,now);return;}
  try(MaterialOutbox q=new MaterialOutbox(root,connection)){q.enqueue(old);MaterialApi api=new MaterialApi(connection,new MaterialTest.Loopback((String)fixture.get("endpoint"),false));if(args[0].equals("first")){yes(api.pump(q,now));yes(row(q).get("error").equals("EXPIRED_ABSENT"));yes(api.pump(q,now));yes(row(q).get("state").equals("server_stored"));}else if(args[0].equals("repeat")){yes(row(q).get("state").equals("server_stored"));yes(!api.pump(q,now));yes(WireJson.list(row(q).get("history")).size()==1);}else throw new IllegalArgumentException("RENEWAL_MODE_INVALID");}
  System.out.println("Material renewal HTTP "+args[0]+": passed");
 }
}
